#include <iostream>
using namespace std;

const int V = 5;
const int INF = 1000000;

int main() {
    int graph[V][V] = {
        {0, 4, 1, 0, 0},
        {4, 0, 2, 5, 0},
        {1, 2, 0, 8, 0},
        {0, 5, 8, 0, 3},
        {0, 0, 0, 3, 0},
    };
    int dist[V];
    bool visited[V];
    for (int i = 0; i < V; i++) {
        dist[i] = INF;
        visited[i] = false;
    }
    dist[0] = 0;
    for (int round = 0; round < V; round++) {
        int u = -1;
        for (int i = 0; i < V; i++) {
            if (!visited[i] && (u == -1 || dist[i] < dist[u])) {
                u = i;
            }
        }
        visited[u] = true;
        for (int v = 0; v < V; v++) {
            if (graph[u][v] > 0 && !visited[v] && dist[u] + graph[u][v] < dist[v]) {
                dist[v] = dist[u] + graph[u][v];
            }
        }
    }
    for (int i = 0; i < V; i++) {
        cout << "0 to " << i << ": " << dist[i] << endl;
    }
    return 0;
}
